wanted=['なぜ C(u, 1)','独立なら','完全に同じ位置なら','コピュラの種類と','比較実験：条件を','コピュラと「潜在']
for b in blocks[1:]:
 if any(b.startswith("'"+x) for x in wanted) or b.startswith("'補足：") or b.startswith("'参考文献"):
  if b.startswith("'比較実験：条件を"):
   b=b[:b.index('const fresh=')]
